tools=[
 ('codex_review · implementation','Исполнитель','Закоммиченная реализация','Фиксирует снимок полного diff; именно этот режим даёт покрытие кода перед merge.','review'),
 ('codex_review · review','Исполнитель','Незакоммиченные изменения','Проверяет рабочий diff. Сам по себе не заменяет implementation-квитанцию.','review'),
 ('codex_review · exec','Исполнитель','План или конкретный файл','Даёт проверку указанного артефакта; это не проверка ещё не написанного кода.','review'),
 ('codex_review · resume=true','Исполнитель','Продолжение того же разговора','Тот же output, mode и модель. Новый запуск не должен покупать новый лимит; сейчас серверного потолка нет.','review'),
 ('record_review_outcome · accepted/disputed/partial','Заказчик ревью','Позиция по замечаниям','Запись позиции автора, а не одобрение от имени ревьюера. Для disputed требуется ссылка на обоснование.','decision'),
 ('record_review_outcome · attested','Автор исправлений','Изменения после ревью','Создаёт проверяемую подпись дельты; файл необходимо закоммитить. Это не новый модельный вызов.','fix'),
 ('record_review_outcome · skipped','Оркестратор','Явно решили обойтись без модели','Фиксирует решение и основание для конкретного снимка. Отдельный автоматический size-skip делает codex_review.','skip'),
 ('bg_list / bg_cancel','Управление фоновыми заданиями','Посмотреть / отменить job','Отмена процесса не отзывает уже сделанное изменение и не заменяет разбор замечаний. Не нужны циклы опроса: завершение обычно будит агента.','receipt'),
 ('merge_worker','Принимающий работу','Провести merge','Покрытие, приёмка, регрессия и фиксация Git проходят внутри операции. operation_id отличает повтор запроса от нового действия.','merge'),
 ('resolve_merge_operation','Принимающий после сверки','Разобрать PARTIAL / UNKNOWN','Сначала выяснить, что реально попало в Git и состояние задачи; затем зафиксировать результат.','done'),
 ('task_create / task_update / task_get','Постановщик и исполнитель по полномочиям','Договорённость о задаче','Создать, изменить или прочитать задание. Task-run платформа ведёт сама, агент не выписывает его вручную.','task'),
 ('check_conflict / switch_worker_branch','Координация веток','Сопутствующие действия','Первый проверяет конфликт веток; второй назначает следующую ветку/задачу после проверок. Качество кода они не оценивают.','work'),
]
